import type { PluginInfoDTO } from '../../../bindings/airmedy/internal/infra/wails/models'

/**
 * The plugin row the Wails binding returns.
 *
 * The generated model under frontend/bindings is the source of truth for the wire
 * shape (it is build output, regenerated by `wails3 generate bindings`); this
 * alias exists so components and their tests import one name instead of each
 * reaching into that directory. See internal/infra/wails/plugin_service.go for
 * the Go side of the same contract.
 */
export type PluginInfo = PluginInfoDTO

/**
 * Status/error wording for a plugin row, already translated by the settings page.
 * Keeping it out of the row component means the row stays presentation-only and
 * its test needs no i18n instance.
 */
export interface PluginRowLabels {
  running: string
  idle: string
  failed: string
  invalid: string
  error: string
  hideError: string
  /**
   * Network wording. `hosts` and `any` are templates: the row fills them with
   * the declared host list, or with the "any address" phrase when the manifest
   * declares the `*` wildcard. Translating here keeps the row presentation-only.
   */
  networkLabel: string
  networkHosts: string
  networkAny: string
  /**
   * KV storage wording. Unlike the network hint this badge describes an enforced
   * right: the host refuses storage.* requests from a plugin that did not declare
   * `permissions.kv`, so the row can state the capability plainly.
   */
  storageLabel: string
}